import sqlite3
from contextlib import contextmanager


class NotesStore:
    def __init__(self, path):
        self._db = sqlite3.connect(path, timeout=5.0, isolation_level=None)
        self._db.row_factory = sqlite3.Row
        self._db.execute('PRAGMA foreign_keys = ON')
        self._db.execute('PRAGMA busy_timeout = 5000')
        self._db.execute(
            'CREATE TABLE IF NOT EXISTS notes ('
            'id INTEGER PRIMARY KEY, '
            'owner_id TEXT NOT NULL, '
            'text TEXT NOT NULL)'
        )
        self._db.execute(
            'CREATE TABLE IF NOT EXISTS note_requests ('
            'owner_id TEXT NOT NULL, '
            'request_id TEXT NOT NULL, '
            'note_id INTEGER NOT NULL REFERENCES notes(id), '
            'UNIQUE(owner_id, request_id))'
        )

    @staticmethod
    def _caller(caller):
        if not isinstance(caller, str) or not caller:
            raise ValueError('invalid caller')
        return caller

    @staticmethod
    def _text(text):
        if not isinstance(text, str) or not text.strip():
            raise ValueError('blank text')
        return text

    @staticmethod
    def _record(row):
        return {'id': row['id'], 'owner_id': row['owner_id'], 'text': row['text']}

    @contextmanager
    def _write(self):
        self._db.execute('BEGIN IMMEDIATE')
        try:
            yield
        except BaseException:
            self._db.rollback()
            raise
        else:
            self._db.commit()

    def create(self, caller, request_id, text):
        caller = self._caller(caller)
        if not isinstance(request_id, str) or not request_id:
            raise ValueError('invalid request id')
        with self._write():
            row = self._db.execute(
                'SELECT n.id, n.owner_id, n.text FROM note_requests r '
                'JOIN notes n ON n.id = r.note_id '
                'WHERE r.owner_id = ? AND r.request_id = ?',
                (caller, request_id),
            ).fetchone()
            if row is not None:
                return self._record(row)
            text = self._text(text)
            note_id = self._db.execute(
                'INSERT INTO notes(owner_id, text) VALUES (?, ?)',
                (caller, text),
            ).lastrowid
            self._db.execute(
                'INSERT INTO note_requests(owner_id, request_id, note_id) '
                'VALUES (?, ?, ?)',
                (caller, request_id, note_id),
            )
            return {'id': note_id, 'owner_id': caller, 'text': text}

    def read(self, caller, note_id):
        caller = self._caller(caller)
        row = self._db.execute(
            'SELECT id, owner_id, text FROM notes WHERE id = ?',
            (note_id,),
        ).fetchone()
        if row is None or row['owner_id'] != caller:
            raise PermissionError('note is unavailable')
        return self._record(row)

    def update(self, caller, note_id, text):
        caller = self._caller(caller)
        with self._write():
            row = self._db.execute(
                'SELECT id, owner_id FROM notes WHERE id = ?',
                (note_id,),
            ).fetchone()
            if row is None or row['owner_id'] != caller:
                raise PermissionError('note is unavailable')
            text = self._text(text)
            self._db.execute('UPDATE notes SET text = ? WHERE id = ?', (text, note_id))
            return {'id': note_id, 'owner_id': caller, 'text': text}

    def close(self):
        self._db.close()

