class NotesStore:
    def __init__(self, path):
        self._lock = threading.Lock()
        self._db = sqlite3.connect(
            path, timeout=10.0, isolation_level=None,
            check_same_thread=False
        )
        self._db.row_factory = sqlite3.Row
        try:
            self._db.execute('''
                CREATE TABLE IF NOT EXISTS notes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    owner_id TEXT NOT NULL,
                    request_id TEXT NOT NULL,
                    text TEXT NOT NULL,
                    original_text TEXT NOT NULL,
                    UNIQUE (owner_id, request_id)
                )
            ''')
        except Exception:
            self._db.close()
            raise

    def create(self, caller, request_id, text):
        with self._lock, self._db:
            self._db.execute('BEGIN IMMEDIATE')
            original = self._db.execute(
                'SELECT id, owner_id, original_text AS text FROM notes '
                'WHERE owner_id = ? AND request_id = ?',
                (caller, request_id)
            ).fetchone()
            if original is not None:
                return dict(original)
            _validate_text(text)
            cursor = self._db.execute(
                'INSERT INTO notes '
                '(owner_id, request_id, text, original_text) '
                'VALUES (?, ?, ?, ?)',
                (caller, request_id, text, text)
            )
            return {
                'id': cursor.lastrowid,
                'owner_id': caller,
                'text': text
            }

    def _read(self, caller, note_id):
        note = self._db.execute(
            'SELECT id, owner_id, text FROM notes '
            'WHERE id = ? AND owner_id = ?',
            (note_id, caller)
        ).fetchone()
        if note is None:
            raise PermissionError('note unavailable')
        return dict(note)

    def read(self, caller, note_id):
        with self._lock:
            return self._read(caller, note_id)

    def update(self, caller, note_id, text):
        with self._lock, self._db:
            self._db.execute('BEGIN IMMEDIATE')
            note = self._read(caller, note_id)
            _validate_text(text)
            self._db.execute(
                'UPDATE notes SET text = ? '
                'WHERE id = ? AND owner_id = ?',
                (text, note_id, caller)
            )
            note['text'] = text
            return note

    def close(self):
        with self._lock:
            self._db.close()

