                owner_id TEXT NOT NULL,
                request_id TEXT NOT NULL,
                text TEXT NOT NULL,
                UNIQUE (owner_id, request_id)
            )
            """
        )

    def _db(self):
        if self._conn is None:
            raise RuntimeError("store is closed")
        return self._conn

    def create(self, caller, request_id, text):
        with self._lock:
            db = self._db()
            db.execute("BEGIN IMMEDIATE")
            try:
                row = db.execute(
                    "SELECT id, owner_id, text FROM notes "
                    "WHERE owner_id = ? AND request_id = ?",
                    (caller, request_id),
                ).fetchone()
                if row is None:
                    _validated_text(text)
