                        cursor = db.execute(
                            "INSERT INTO notes (owner_id, request_id, text) "
                            "VALUES (?, ?, ?)",
                            (caller, request_id, text),
                        )
                        row = db.execute(
                            "SELECT id, owner_id, text FROM notes WHERE id = ?",
                            (cursor.lastrowid,),
                        ).fetchone()
                    except sqlite3.IntegrityError:
                        row = db.execute(
                            "SELECT id, owner_id, text FROM notes "
                            "WHERE owner_id = ? AND request_id = ?",
                            (caller, request_id),
                        ).fetchone()
                        if row is None:
                            raise
                db.execute("COMMIT")
            except BaseException:
                if db.in_transaction:
                    db.execute("ROLLBACK")
                raise
            return _note(row)

    def read(self, caller, note_id):
        with self._lock:
            row = self._db().execute(
                "SELECT id, owner_id, text FROM notes WHERE id = ?",
                (note_id,),
