            try:
                row = db.execute(
                    "SELECT id, owner_id, text FROM notes WHERE id = ?",
                    (note_id,),
                ).fetchone()
                if row is None or row[1] != caller:
                    raise PermissionError("note is unavailable")
                _validated_text(text)
                db.execute(
                    "UPDATE notes SET text = ? WHERE id = ? AND owner_id = ?",
                    (text, note_id, caller),
